    {services && <section className="px-8 py-20 md:px-14"><span className="font-sans text-[9px] uppercase tracking-[.2em]">02 / Appointments</span><div className="mt-10 divide-y divide-black/20 border-y border-black/20">{(services.highlights?.length ? services.highlights : [services.body]).map((item, index) => <div key={item} className="grid gap-6 py-7 md:grid-cols-[100px_1fr_auto]"><span className="font-sans text-xs">0{index + 1}</span><h3 className="text-2xl font-normal">{item}</h3><span className="font-sans text-[9px] uppercase tracking-[.15em]">Enquire →</span></div>)}</div></section>}
