    <section className="relative border-b-2 border-black px-6 py-16 md:px-12"><div className="absolute right-8 top-8 rotate-6 rounded-full border-2 border-black bg-[#ffd53d] px-5 py-8 text-center text-xs font-black uppercase">{props.brief.programmeCapacity || "A clear place to start"}</div><div className="max-w-5xl"><span className="text-[10px] font-black uppercase tracking-[.2em]">{props.brief.offer}</span><Editable part="headline" props={props} className="mt-7"><h1 className={cn("max-w-5xl font-black uppercase leading-[.82] tracking-[-.075em]", props.narrow ? "text-6xl" : "text-[7.5rem]")}>{props.copy.headline}</h1></Editable><Editable part="subheadline" props={props} className="mt-9 max-w-2xl text-xl font-bold leading-8">{props.copy.subheadline}</Editable><div className="mt-9"><PrimaryAction props={props} dark /></div></div></section>
    {props.brief.primaryProblem && <section className="border-b-2 border-black bg-[#ff4937] px-6 py-16 md:px-12"><span className="text-[10px] font-black uppercase tracking-[.2em]">You may be here because</span><h2 className="mt-5 max-w-4xl text-5xl font-black uppercase leading-[.95] tracking-[-.05em]">{props.brief.primaryProblem}</h2></section>}
    {steps.length > 0 && <section className="border-b-2 border-black px-6 py-16 md:px-12"><span className="text-[10px] font-black uppercase tracking-[.2em]">The route</span><h2 className="mt-4 text-5xl font-black uppercase">One clear job at a time.</h2><div className={cn("mt-10 grid border-2 border-black", props.narrow ? "grid-cols-1" : "grid-cols-4")}>{steps.map((item, index) => <div key={item} className="min-h-56 border-black p-5 md:border-r-2 last:border-r-0"><span className="text-xs font-black">0{index + 1}</span><p className="mt-16 text-xl font-black leading-6">{item}</p></div>)}</div></section>}
    {services && <section className="grid gap-10 border-b-2 border-black bg-[#ffd53d] px-6 py-16 md:grid-cols-2 md:px-12"><div><span className="text-[10px] font-black uppercase tracking-[.2em]">What is included</span><h2 className="mt-4 text-5xl font-black uppercase">{services.title}</h2></div><div><p className="text-lg font-bold leading-8">{services.body}</p>{services.highlights?.map((item) => <div key={item} className="border-t-2 border-black py-4 font-black">{item}</div>)}</div></section>}
    {(props.brief.faqQuestion || props.brief.objections) && <section className="px-6 py-16 md:px-12"><span className="text-[10px] font-black uppercase tracking-[.2em]">Know before you choose</span><h2 className="mt-4 text-5xl font-black uppercase">A straight answer.</h2><div className="mt-9 max-w-3xl border-y-2 border-black py-6"><b>{props.brief.faqQuestion || props.brief.objections}</b><p className="mt-3 leading-7">{props.brief.faqAnswer || props.copy.about}</p></div></section>}
